--STEP 1: DEPLOY THIS SP @ DBTRANS.CustDB -----
------------------------------------------------------
ALTER PROCEDURE [dbo].[Acc_CustSetting3rd_19]
	@srecommend INT	
	,@sdiscount DECIMAL (9,8)
	,@maxcustid INT
	,@target VARCHAR(20)
AS
BEGIN	
	SET NOCOUNT ON;
	
	IF (@target = 'REPLICATED' AND @@SERVERNAME = 'DBTRANS') RETURN	-- run at all replicated servers
	IF (@target = 'DBTRANS' AND @@SERVERNAME <> 'DBTRANS') RETURN -- run at dbtrans only
	
	IF (SELECT COUNT(1)
		FROM sys.objects
		WHERE NAME IN ('CustInfo','CustSettingGame') AND type = 'U'
		) <> 2 RETURN	
	
	UPDATE cs
	SET adiscount = CASE WHEN ci.roleid IN (3,1) THEN @sdiscount ELSE 0 END,
		discount = CASE WHEN ci.roleid IN (2,1) THEN @sdiscount ELSE 0 END,
		playerdiscount = CASE WHEN ci.roleid = 1 THEN @sdiscount ELSE 0 END,
		sdiscount = CASE WHEN ci.roleid = 1 THEN @sdiscount ELSE 0 END
	FROM CustSettingGame cs WITH (UPDLOCK,ROWLOCK)
		inner join custInfo ci WITH (NOLOCK) ON cs.custid = ci.custid
	WHERE ci.srecommend = @srecommend
		AND cs.custid <= @maxcustid		
		AND cs.sporttype = 162
		AND 1 <> CASE WHEN ci.roleid = 3 AND cs.adiscount = @sdiscount AND cs.sdiscount = 0
		                   AND cs.discount = 0 AND cs.playerdiscount = 0 THEN 1 
					  WHEN ci.roleid = 2 AND cs.discount = @sdiscount AND cs.sdiscount = 0
						   AND cs.adiscount = 0 AND cs.playerdiscount = 0 THEN 1 
					  WHEN ci.roleid = 1 AND cs.playerdiscount = @sdiscount AND cs.sdiscount = @sdiscount
					       AND cs.adiscount = @sdiscount AND cs.discount = @sdiscount THEN 1
					  ELSE 0 END
		AND ci.roleid IN (3,2,1)  	
END	
GO
-- END STEP 1: DEPLOY THIS SP @ DBTRANS.CustDB -------
------------------------------------------------------	

